// Кейс: .qa/tests/monitoring/MON-027.md (шаги 1–2) · план: .qa/e2e-app/specs/app.md (1.37)
// Один телефон в аккаунте: строка-предупреждение ⚠ «טלפון נוסף מחובר — ההתרעה תגיע רק לטלפון הזה», «4 מתוך 5», «המשך» активна.
// РУЧНОЕ ПРЕДУСЛОВИЕ: второй телефон удалён из аккаунта → запуск с BANCI_ONE_PHONE=1 (иначе пропуск). «המשך» не нажимается.
import { by, assert, skip } from '../../lib/appium.mjs';
import { openSafetyCheck, waitEnabled } from '../../lib/banci.mjs';

export const name = 'בדיקת בטיחות с одним телефоном: ⚠ «טלפון נוסף מחובר — ההתרעה תגיע רק לטלפון הזה», «4 מתוך 5», «המשך» активна (ручное предусловие BANCI_ONE_PHONE) #4a869b @iphone @app @prod-safe';
const ONE_PHONE_ROW = 'ההתרעה תגיע רק לטלפון הזה';

export default async function (app) {
  if (process.env.BANCI_ONE_PHONE !== '1') skip('второй телефон удаляется вручную: удалить его из «מכשירים» и запустить с BANCI_ONE_PHONE=1; после — вернуть по QR (DEV-012)');

  const counter = await openSafetyCheck(app);
  await app.waitFor(by.contains(ONE_PHONE_ROW), { timeout: 20000, what: 'строка «טלפון נוסף מחובר — ההתרעה תגיע רק לטלפון הזה» (если её нет — в аккаунте ещё есть второй телефон)' });
  const label = String(await counter.attr('label') ?? await counter.attr('name'));
  assert(label.includes('4 מתוך 5'), `счётчик «4 מתוך 5», а сейчас «${label}» («מה רצוי» #4a869b)`);
  const next = await app.waitFor(by.exact('המשך', 'Button'), { what: '«המשך» на «בדיקת בטיחות»' });
  await waitEnabled(next, true, { timeout: 15000, what: '«המשך» при одном телефоне (предупреждение, не блок)' });
  await app.screenshot('4a869b-auto-safety-one-phone');
  await app.restart();
}
